 if(event.target.closest('#composer')){state.composerDrafts[state.active]={text:$('#composer textarea').value,role:$('#composer select').value};setContactComposer(current(),state.composerDrafts[state.active]);saveProgress();}
 if(event.target.id==='reply-draft'){state.replyDrafts[state.tone]=event.target.value;updateReplyVerification();const pending=needsReplyDetails(event.target.value),quick=$('.analysis-quick-copy'),note=$('.reply-placeholder-note');if(quick)quick.disabled=!!replyCopyProblem(event.target.value);if(note)note.hidden=!pending;saveProgress(true);}
 if(event.target.closest('.review-row'))updateReviewSummary();
